  /* ---------------- the journeys (Acts, King James words; other languages from their Bibles) ---------------- */
  /* stop: [city, how Paul came (start | land | sea), verse that names the place, what happened, icon, effect, extra help] */
  var JOURNEYS = [
    { name: 'Paul’s First Journey', ref: 'Acts 13–14', intro: 'The church in Antioch prayed and fasted, and the Holy Spirit sent Paul and Barnabas to tell the world about Jesus. Follow them!', stops: [
      ['Antioch', 'start', ['Acts', 13, 2, 2, 'As they ministered to the Lord, and fasted, the Holy Ghost said, Separate me Barnabas and Saul for the work whereunto I have called them.'], 'Paul and Barnabas are sent out by the church in Antioch.', '⛪'],
      ['Seleucia', 'land', ['Acts', 13, 4, 4, 'So they, being sent forth by the Holy Ghost, departed unto Seleucia; and from thence they sailed to Cyprus.'], 'They go down to the port and board a ship.', '⚓'],
      ['Salamis', 'sea', ['Acts', 13, 5, 5, 'And when they were at Salamis, they preached the word of God in the synagogues of the Jews: and they had also John to their minister.'], 'On the island of Cyprus they preach in the synagogues.', '📜'],
      ['Paphos', 'land', ['Acts', 13, 6, 6, 'And when they had gone through the isle unto Paphos, they found a certain sorcerer, a false prophet, a Jew, whose name was Bar-jesus:'], 'The governor, Sergius Paulus, hears the word of God and believes!', '🏛️'],
      ['Perga', 'sea', ['Acts', 13, 13, 13, 'Now when Paul and his company loosed from Paphos, they came to Perga in Pamphylia: and John departing from them returned to Jerusalem.'], 'They sail to the mainland. Young John Mark goes home to Jerusalem.', '⛵'],
      ['Pisidian Antioch', 'land', ['Acts', 13, 14, 14, 'But when they departed from Perga, they came to Antioch in Pisidia, and went into the synagogue on the sabbath day, and sat down.'], 'Paul preaches in the synagogue, and many people are glad to hear about Jesus.', '🙌'],
      ['Iconium', 'land', ['Acts', 13, 51, 51, 'But they shook off the dust of their feet against them, and came unto Iconium.'], 'A great crowd of Jews and Greeks believe.', '👥'],
      ['Lystra', 'land', ['Acts', 14, 6, 6, 'They were ware of it, and fled unto Lystra and Derbe, cities of Lycaonia, and unto the region that lieth round about:'], 'Paul says to a man who had never walked: “Stand upright on thy feet!” And he leaps and walks!', '🦶'],
      ['Derbe', 'land', ['Acts', 14, 20, 20, 'Howbeit, as the disciples stood round about him, he rose up, and came into the city: and the next day he departed with Barnabas to Derbe.'], 'Many become disciples. Then Paul and Barnabas go back, encouraging the new churches, and sail home to Antioch.', '✝️']
    ] },
    { name: 'Paul’s Second Journey', ref: 'Acts 15–18', intro: 'Paul sets out again, this time with Silas, to visit the churches and to take the Gospel even further: all the way to Europe!', stops: [
      ['Antioch', 'start', ['Acts', 15, 40, 40, 'And Paul chose Silas, and departed, being recommended by the brethren unto the grace of God.'], 'Paul chooses Silas, and they set off together.', '⛪'],
      ['Derbe', 'land', ['Acts', 16, 1, 1, 'Then came he to Derbe and Lystra: and, behold, a certain disciple was there, named Timotheus, the son of a certain woman, which was a Jewess, and believed; but his father was a Greek:'], 'Paul visits the churches he began on his first journey.', '⛪'],
      ['Lystra', 'land', ['Acts', 16, 2, 2, 'Which was well reported of by the brethren that were at Lystra and Iconium.'], 'Young Timothy joins Paul and Silas.', '🧑'],
      ['Troas', 'land', ['Acts', 16, 8, 8, 'And they passing by Mysia came down to Troas.'], 'In the night Paul sees a vision: a man of Macedonia says, “Come over into Macedonia, and help us.”', '🌙'],
      ['Philippi', 'sea', ['Acts', 16, 12, 12, 'And from thence to Philippi, which is the chief city of that part of Macedonia, and a colony: and we were in that city abiding certain days.'], 'Lydia believes. Paul and Silas are put in prison, but at midnight they pray and sing, and an earthquake opens the doors!', '⛓️', 'quake'],
      ['Thessalonica', 'land', ['Acts', 17, 1, 1, 'Now when they had passed through Amphipolis and Apollonia, they came to Thessalonica, where was a synagogue of the Jews:'], 'Paul preaches that Jesus is the Christ, and some believe.', '📜'],
      ['Berea', 'land', ['Acts', 17, 10, 10, 'And the brethren immediately sent away Paul and Silas by night unto Berea: who coming thither went into the synagogue of the Jews.'], 'The people of Berea search the Scriptures every day to see if these things are true.', '📖'],
      ['Athens', 'sea', ['Acts', 17, 15, 15, 'And they that conducted Paul brought him unto Athens: and receiving a commandment unto Silas and Timotheus for to come to him with all speed, they departed.'], 'Paul finds an altar “TO THE UNKNOWN GOD” and tells the Athenians about the true God.', '🏛️'],
      ['Corinth', 'land', ['Acts', 18, 1, 1, 'After these things Paul departed from Athens, and came to Corinth;'], 'Paul makes tents with Priscilla and Aquila. The Lord tells him: “Be not afraid… for I am with thee.”', '⛺'],
      ['Ephesus', 'sea', ['Acts', 18, 19, 19, 'And he came to Ephesus, and left them there: but he himself entered into the synagogue, and reasoned with the Jews.'], 'A short visit. Paul promises: “I will return again unto you, if God will.”', '👋'],
      ['Caesarea', 'sea', ['Acts', 18, 22, 22, 'And when he had landed at Cæsarea, and gone up, and saluted the church, he went down to Antioch.'], 'Paul lands, greets the church, and goes home to Antioch. What a journey!', '⚓']
    ] },
    { name: 'Paul’s Third Journey', ref: 'Acts 18–21', intro: 'Paul travels again to strengthen the disciples. He stays a long time in Ephesus, then visits Greece and sails back toward Jerusalem.', stops: [
      ['Antioch', 'start', ['Acts', 18, 23, 23, 'And after he had spent some time there, he departed, and went over all the country of Galatia and Phrygia in order, strengthening all the disciples.'], 'Paul sets out to strengthen all the disciples.', '⛪'],
      ['Ephesus', 'land', ['Acts', 19, 1, 1, 'And it came to pass, that, while Apollos was at Corinth, Paul having passed through the upper coasts came to Ephesus: and finding certain disciples,'], 'Paul teaches for two years, and all Asia hears the word of the Lord. Then a crowd starts a riot, shouting: “Great is Diana of the Ephesians!”', '📣', 'crowd'],
      ['Philippi', 'sea', ['Acts', 20, 1, 1, 'And after the uproar was ceased, Paul called unto him the disciples, and embraced them, and departed for to go into Macedonia.'], 'Paul encourages the believers in Macedonia.', '🤗', null, 'Find the city in Macedonia where Lydia lived.'],
      ['Corinth', 'land', ['Acts', 20, 2, 3, 'And when he had gone over those parts, and had given them much exhortation, he came into Greece, And there abode three months.'], 'Paul stays three months in Greece.', '⛪', null, 'Find the great city of Greece where Paul made tents.'],
      ['Troas', 'sea', ['Acts', 20, 6, 6, 'And we sailed away from Philippi after the days of unleavened bread, and came unto them to Troas in five days; where we abode seven days.'], 'Paul preaches until midnight. Young Eutychus falls asleep and falls from a window, but God brings him back to life!', '🪟'],
      ['Miletus', 'sea', ['Acts', 20, 15, 15, 'And we sailed thence, and came the next day over against Chios; and the next day we arrived at Samos, and tarried at Trogyllium; and the next day we came to Miletus.'], 'Paul says goodbye to the elders of Ephesus: “It is more blessed to give than to receive.” They all weep and pray.', '🙏'],
      ['Rhodes', 'sea', ['Acts', 21, 1, 1, 'And it came to pass, that after we were gotten from them, and had launched, we came with a straight course unto Coos, and the day following unto Rhodes, and from thence unto Patara:'], 'Sailing on, island by island.', '⛵'],
      ['Tyre', 'sea', ['Acts', 21, 3, 3, 'Now when we had discovered Cyprus, we left it on the left hand, and sailed into Syria, and landed at Tyre: for there the ship was to unlade her burden.'], 'The disciples and their families kneel down on the beach and pray with Paul.', '🏖️'],
      ['Caesarea', 'sea', ['Acts', 21, 8, 8, 'And the next day we that were of Paul’s company departed, and came unto Cæsarea: and we entered into the house of Philip the evangelist, which was one of the seven; and abode with him.'], 'They stay with Philip the evangelist. Paul says he is ready even to die for the Lord Jesus.', '🏠'],
      ['Jerusalem', 'land', ['Acts', 21, 17, 17, 'And when we were come to Jerusalem, the brethren received us gladly.'], 'The brethren welcome Paul gladly. Later he is arrested, but the Lord tells him: “Be of good cheer, Paul”: he will bear witness in Rome too.', '✨']
    ] },
    { name: 'Voyage to Rome', ref: 'Acts 27–28', intro: 'Paul is a prisoner, but God has a plan: Paul must tell the Good News in Rome. Sail with him across the Great Sea!', stops: [
      ['Caesarea', 'start', ['Acts', 27, 1, 1, 'And when it was determined that we should sail into Italy, they delivered Paul and certain other prisoners unto one named Julius, a centurion of Augustus’ band.'], 'Paul is put on a ship with other prisoners and a kind centurion named Julius.', '⛓️'],
      ['Sidon', 'sea', ['Acts', 27, 3, 3, 'And the next day we touched at Sidon. And Julius courteously entreated Paul, and gave him liberty to go unto his friends to refresh himself.'], 'Julius lets Paul visit his friends.', '🤝'],
      ['Myra', 'sea', ['Acts', 27, 5, 5, 'And when we had sailed over the sea of Cilicia and Pamphylia, we came to Myra, a city of Lycia.'], 'They change to a big grain ship from Alexandria, sailing to Italy.', '🚢'],
      ['Fair Havens', 'sea', ['Acts', 27, 8, 8, 'And, hardly passing it, came unto a place which is called The fair havens; nigh whereunto was the city of Lasea.'], 'Paul warns that the voyage will be dangerous, but they sail on…', '⚠️'],
      ['Malta', 'sea', ['Acts', 28, 1, 1, 'And when they were escaped, then they knew that the island was called Melita.'], 'The ship breaks apart, but everyone reaches the island safely! A viper bites Paul’s hand, but he shakes it off into the fire and feels no harm.', '🔥', 'storm'],
      ['Syracuse', 'sea', ['Acts', 28, 12, 12, 'And landing at Syracuse, we tarried there three days.'], 'Three days in Sicily.', '⛵'],
      ['Rhegium', 'sea', ['Acts', 28, 13, 13, 'And from thence we fetched a compass, and came to Rhegium: and after one day the south wind blew, and we came the next day to Puteoli:'], 'The south wind blows them north.', '🌬️'],
      ['Puteoli', 'sea', ['Acts', 28, 13, 13, 'And from thence we fetched a compass, and came to Rhegium: and after one day the south wind blew, and we came the next day to Puteoli:'], 'They find Christian brothers there and stay seven days.', '🤝'],
      ['Rome', 'land', ['Acts', 28, 16, 16, 'And when we came to Rome, the centurion delivered the prisoners to the captain of the guard: but Paul was suffered to dwell by himself with a soldier that kept him.'], 'In Rome, Paul preaches the Kingdom of God and teaches about the Lord Jesus Christ with all confidence.', '🏛️']
    ] }
  ];
  var STORM = ['Acts', 27, 24, 24, 'Saying, Fear not, Paul; thou must be brought before Cæsar: and, lo, God hath given thee all them that sail with thee.'];

