      var over = el('div', { class: 'kpj-over', hidden: 'hidden' }), stormFx = el('div', { class: 'kpj-storm', hidden: 'hidden' }, [el('i', { class: 'kpj-rain' }), el('i', { class: 'kpj-flash' })]);
      view.appendChild(svg); view.appendChild(stormFx); view.appendChild(zoomBar); view.appendChild(over);
      game.appendChild(panel); game.appendChild(view);

