      function clampCam(c) { fitAR(); var w = Math.max(240, Math.min(W, H / AR, c.w)), h = w * AR; return { w: w, x: Math.max(0, Math.min(W - w, c.x)), y: Math.max(0, Math.min(H - h, c.y)) }; }
