      function zoomAt(f, at) { var c = { w: cam.w * f }; c.x = at[0] - (at[0] - cam.x) * f; c.y = at[1] - (at[1] - cam.y) * f; setCam(c); }
      function zoomBy(f) { var at = [cam.x + cam.w / 2, cam.y + cam.w * AR / 2], c = { w: cam.w * f }; c.x = at[0] - (at[0] - cam.x) * f; c.y = at[1] - (at[1] - cam.y) * f; flyTo(c, 350); }
      svg.addEventListener('wheel', function (e) { e.preventDefault(); if (anim) { cancelAnimationFrame(anim); anim = null; } zoomAt(e.deltaY > 0 ? 1.15 : 1 / 1.15, toMap(e)); }, { passive: false });
