      function up(e) { /* the map captures the pointer, so a tap on a city is read here, not from a click */ if (e.type === 'pointerup' && !moved && downCity && Object.keys(pts).length === 1) { var nm = downCity.getAttribute('data-city'); downCity = null; if (nm) tap(nm); } delete pts[e.pointerId]; if (!Object.keys(pts).length) drag = null; else if (drag) { drag.cam = cam; var k = Object.keys(pts)[0]; drag.at = pts[k]; drag.d = null; } }
