        var lab = labels ? '<text class="kpj-city__t" x="' + L[0] + '" y="' + (L[1] + 5) + '" text-anchor="' + (L[2] === 'e' ? 'end' : L[2] === 'm' ? 'middle' : 'start') + '">' + esc(T(name)) + '</text>' : '';
        g.innerHTML = '<circle class="kpj-city__hit" r="26" fill="transparent"/><circle class="kpj-city__ring" r="15" fill="none"/><g class="kpj-city__icon"><rect x="-7" y="-9" width="14" height="12" fill="#e9d7ae" stroke="#7a5a2a" stroke-width="1.5"/><path d="M-9 -9 L0 -16 L9 -9 Z" fill="#b3122e" stroke="#7a2a1a" stroke-width="1"/><rect x="-2" y="-4" width="4" height="7" fill="#7a5a2a"/></g>' + lab;
        g.setAttribute('data-city', name); g.addEventListener('keydown', function (e) { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); tap(name); } });
